import logging
import re
import traceback
from datetime import datetime
from taf.internal.managedobject import ManagedObject
from taf.transport.ssh import CommandOutputTimeoutError
from .exception import PyroServerStartFailure, TryServeralTimesFailure
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from .util import try_several_times, try_several_times_with_timeout_increment
from taf.internal.rpc.pyro.server.feature_package import FeaturePackage


class PyroServerRunner(ManagedObject):
    _PYRO_SERVER_START_FILE_NAME = "start"
    _SUCCESS_MESSAGE_TEMPLATE = 'pyro sever ready with uri:{}, pid:{}'
    _SERVER_DEBUG_LOG_NAME = 'pyro_server_debug.log'
    _STARTUP_LOG_FILE_EXISTENCE_CHECK_TRIES = 6
    _STARTUP_LOG_CONTENT_EXISTENCE_CHECK_TRIES = 5

    @classmethod
    def create_server_uri(cls, hostname, port):
        return "PYRO:{}@{}:{}".format(cls.__name__, hostname, port)

    def __init__(self, hostname, port, server_dir=None,
                 ssh_user_name=None, ssh_password=None, python_path=None, packages=None, log_dir=None, **kwargs):
        super(PyroServerRunner, self).__init__(**kwargs)
        self._pid = None
        self._hostname = hostname
        self._ssh_user_name = ssh_user_name
        self._ssh_password = ssh_password
        self._server_dir = server_dir or ""
        self._port = port
        self._pyro_uri = self.create_server_uri(self._hostname, self._port)
        self._python_path = python_path or 'python'
        self._packages = packages

        log_dir = log_dir or (server_dir + '/logs/')
        timestamp = datetime.today().strftime("%Y%m%dT%H%M%S%f")
        self._SERVER_DEBUG_LOG_NAME = "{}_{}".format(timestamp, self._SERVER_DEBUG_LOG_NAME)
        self._log_path = log_dir + self._SERVER_DEBUG_LOG_NAME
        self._start_command = "cd {dir};{python_cmd}".format(
            dir=server_dir,
            python_cmd=self._generate_start_command())

        self._ssh_connection = ManagedSshConnection(self._hostname, ssh_user_name, ssh_password)
        self.add_prerequisite(self._ssh_connection)

    def _get_pyro_server_start_file_name(self):
        return self._PYRO_SERVER_START_FILE_NAME

    def _get_success_message_template(self):
        return self._SUCCESS_MESSAGE_TEMPLATE

    def _get_default_server_debug_log_file_name(self):
        return self._SERVER_DEBUG_LOG_NAME

    def _get_startup_log_file_existence_check_tries(self):
        return self._STARTUP_LOG_FILE_EXISTENCE_CHECK_TRIES

    def _get_startup_log_content_check_tries(self):
        return self._STARTUP_LOG_CONTENT_EXISTENCE_CHECK_TRIES

    @property
    def uri(self):
        return self._pyro_uri

    @property
    def server_pid(self):
        return self._pid

    @property
    def server_dir(self):
        return self._server_dir

    @property
    def server_log_path(self):
        return self._log_path

    @property
    def pyro_server_packages(self):
        return self._packages

    def _setup(self):
        self._start()

    def _start(self):
        logging.debug("execute start command is: {}".format(self._start_command))
        self._ssh_connection.ssh_connection.send_command(self._start_command, get_pty=True)

        log = self._get_start_log()
        pid = self._parse_server_pid_from_log(log)
        if not pid:
            raise PyroServerStartFailure(log)

        self._pid = pid
        logging.info("server was started up with log {}".format(log))

    def _get_start_log(self):
        monitor_ssh_connection = ManagedSshConnection(self._hostname, self._ssh_user_name, self._ssh_password)
        monitor_ssh_connection.setup()

        try:
            try_several_times(self._check_start_log_existence, tries=self._get_startup_log_file_existence_check_tries(),
                              interval=10, timeout=30, ssh_connection=monitor_ssh_connection)
            log = try_several_times_with_timeout_increment(self._check_startup_message,
                                                           tries=self._get_startup_log_content_check_tries(),
                                                           interval=3,
                                                           start_timeout=5,
                                                           timeout_increment=10,
                                                           ssh_connection=monitor_ssh_connection)
        except TryServeralTimesFailure as e:
            monitor_ssh_connection.teardown()
            logging.error('exception is {}, traceback is {}'.format(e, traceback.format_exc()))
            raise PyroServerStartFailure(e)
        finally:
            monitor_ssh_connection.teardown()
        return log

    def _check_startup_message(self, timeout, ssh_connection=None):
        logging.info("trying verifying startup message with timeout {}".format(timeout))
        try:
            ssh_process = ssh_connection.ssh_connection.send_command(
                "cat {server_log_file}".format(server_log_file=self._log_path), get_pty=True)
            log = ssh_process.read_output_until('\r', timeout=timeout)
            if log.strip():
                return log
        except CommandOutputTimeoutError as e:
            logging.info("failed to get server debug log for pyro startup report for {}, traceback is {}".
                         format(e, traceback.format_exc()))
        return ""

    def _check_start_log_existence(self, timeout, ssh_connection=None):
        logging.info("trying check startup log existence with timeout {}".format(timeout))
        ssh_process = ssh_connection.ssh_connection.send_command("ls {}".format(self._log_path), get_pty=True)

        try:
            output = ssh_process.read_output_until(self._log_path, timeout=timeout)
        except CommandOutputTimeoutError as e:
            logging.info("failed to get ls result {} seconds timeout for {}， traceback is {}".
                         format(timeout, e, traceback.format_exc()))
            return False
        return "cannot access" not in output

    def _stop(self):
        """
        server will be stopped automatically with the ssh connection teardown
        :return:
        """
        logging.info("server was shutting down")
        if not self._check_start_log_existence(timeout=30, ssh_connection=self._ssh_connection):
            logging.info("there is not server log ({}) generated, unable to download server log".format(self._log_path))

    def _teardown(self):
        self._stop()

    def _get_remote_info_from_packages(self):
        if self._packages:
            return [package.remote.to_dict() for package in self._packages]

        return [FeaturePackage.Remote(object_id=self.__class__.__name__,
                                      server_package_name='./',
                                      exposed_module_name='start',
                                      exposed_class_name='Server').to_dict(), ]

    def _generate_start_command(self):
        #  server_ip_address, server_port, object_id, library_folder, exposed__package, exposed_class
        start_pyro_server_cmd = "{} -m {} {} {} {} {} {}".format(
            self._python_path,
            self._PYRO_SERVER_START_FILE_NAME,
            self._hostname,
            self._port,
            '"' + str(self._get_remote_info_from_packages()) + '"',
            '"' + self._SUCCESS_MESSAGE_TEMPLATE + '"',
            '"' + self._log_path + '"'
        )
        return start_pyro_server_cmd

    def _parse_server_pid_from_log(self, log):
        if not log:
            return None

        pattern_str = self._SUCCESS_MESSAGE_TEMPLATE.format(r'(.*)', r'(\d+)')
        pattern = re.compile(pattern_str)
        result = pattern.search(log)
        return result.group(2) if result else None
